export function fortnightActivityView(s){const def=fortnightActivities[s.day];if(!def||s.location!==def.place||s.clock.minute<780||s.clock.minute+15>1320)return null;const record=s.fortnightLife?.[s.day];if(record?.done)return null;return {...def,step:record?.step??0,choice:record?.choice??null};}
export function progressFortnightActivity(state,id){const view=fortnightActivityView(state);if(!view)throw new Error('오늘 이 장소에서 이어갈 활동이 없습니다.');const choice=view.step===0?view.choices.find(c=>c[0]===id):view.choices.find(c=>c[0]===view.choice);if(!choice||view.step===1&&id!=='finish')throw new Error('현재 단계의 행동을 확인해 주세요.');let s=advanceFreeTime(state,15);s.fortnightLife??={};if(view.step===0){s.fortnightLife[s.day]={step:1,choice:id,done:false};s.lastResult=choice[2]+' 남은 메모와 주변 자리를 정리하자.';}else{s.fortnightLife[s.day]={step:2,choice:view.choice,done:true};s.memory.push(`[${s.day}일차] ${view.title}: ${choice[2]}`);s.freeDay??={completed:[],settled:false};s.freeDay.completed.push({id:view.title,start:s.clock.minute-30,end:s.clock.minute});s.known.push(...(s.known.includes(view.title+' 기록')?[]:[view.title+' 기록']));s.lastResult=choice[2]+' 사용한 자리를 정리하고 하던 일로 돌아간다.';}s.pace={count:0,seen:{}};return s;}
